 528	// Resolve takes a CommitSpec and returns a Commit, or an error if the commit cannot be found.
 529	// If the CommitSpec is HEAD, Resolve also needs the DoltRef of the current working branch.
 530	func (ddb *DoltDB) Resolve(ctx context.Context, cs *CommitSpec, cwb ref.DoltRef) (*OptionalCommit, error) {
 531		if cs == nil {
 532			panic("nil commit spec")
 533		}
 534	
 535		hash, err := ddb.getHashFromCommitSpec(ctx, cs, cwb, hash.Hash{})
 536		if err != nil {
 537			return nil, err
 538		}
 539	
 540		commitValue, err := datas.LoadCommitAddr(ctx, ddb.vrw, *hash)
 541		if err != nil {
 542			return nil, err
 543		}
 544	
 545		if commitValue.IsGhost() {
 546			return &OptionalCommit{nil, *hash}, nil
 547		}
 548	
 549		commit, err := NewCommit(ctx, ddb.vrw, ddb.ns, commitValue)
 550		if err != nil {
 551			return nil, err
 552		}
 553	
 554		return commit.GetAncestor(ctx, cs.aSpec)
 555	}
