 557	// ResolveHash takes a hash and returns an OptionalCommit directly.
 558	// This assumes no ancestor spec resolution and no current working branch (cwb) needed.
 559	func (ddb *DoltDB) ResolveHash(ctx context.Context, h hash.Hash) (*OptionalCommit, error) {
 560		if oc, ok := ddb.commitCache.Get(h); ok {
 561			return oc, nil
 562		}
 563		commitValue, err := datas.LoadCommitAddr(ctx, ddb.vrw, h)
 564		if err != nil {
 565			return nil, err
 566		}
 567		oc := &OptionalCommit{Addr: h}
 568		if !commitValue.IsGhost() {
 569			commit, err := NewCommit(ctx, ddb.vrw, ddb.ns, commitValue)
 570			if err != nil {
 571				return nil, err
 572			}
 573			oc.Commit = commit
 574		}
 575		ddb.commitCache.Add(h, oc)
 576		return oc, nil
 577	}
