 579	// BootstrapShallowResolve is a special case of Resolve that is used to resolve a commit prior to pulling it's history
 580	// in a shallow clone. In general, application code should call Resolve and get an OptionalCommit. This is a special case
 581	// where we need to get the head commit for the commit closure used to determine what commits should skipped.
 582	func (ddb *DoltDB) BootstrapShallowResolve(ctx context.Context, cs *CommitSpec) (prolly.CommitClosure, error) {
 583		if cs == nil {
 584			panic("nil commit spec")
 585		}
 586	
 587		hash, err := ddb.getHashFromCommitSpec(ctx, cs, nil, hash.Hash{})
 588		if err != nil {
 589			return prolly.CommitClosure{}, err
 590		}
 591	
 592		commitValue, err := datas.LoadCommitAddr(ctx, ddb.vrw, *hash)
 593		if err != nil {
 594			return prolly.CommitClosure{}, err
 595		}
 596	
 597		if commitValue.IsGhost() {
 598			return prolly.CommitClosure{}, ErrGhostCommitEncountered
 599		}
 600	
 601		return getCommitClosure(ctx, commitValue, ddb.vrw, ddb.ns)
 602	}
